import{_ as S,a0 as p,w as D,s as O,ao as l,I as a,x as o,a1 as r,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"FreeDOS： 已經積極開發了 23 年的 DOS | LCTT x X-CMD","titleTemplate":false,"description":"FreeDOS： 已經積極開發了 23 年的 DOS | LCTT (201707) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"FreeDOS： 已經積極開發了 23 年的 DOS | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"FreeDOS： 已經積極開發了 23 年的 DOS | LCTT (201707) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201707/20170629 4 cool facts you should know about FreeDOS","title":"FreeDOS： 已經積極開發了 23 年的 DOS","tag":"201707","desc":""},"relativePath":"201707/20170629 4 cool facts you should know about FreeDOS.md","filePath":"[post].md"}'),i={name:"201707/20170629 4 cool facts you should know about FreeDOS.md"};function n(d,e,u,f,m,F){const t=p("Link");return D(),O("div",null,[e[16]||(e[16]=l('<h1 id="freedos-已經積極開發了-23-年的-dos" tabindex="-1">FreeDOS： 已經積極開發了 23 年的 DOS <a class="header-anchor" href="#freedos-已經積極開發了-23-年的-dos" aria-label="Permalink to “FreeDOS： 已經積極開發了 23 年的 DOS”">​</a></h1><blockquote><p>23 年後，FreeDOS 仍在積極開發，並將 MS-DOS 的生命延長了幾年</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/images/life/wings_freedos_game.jpg?itok=3O_GB-7o" alt="4 cool facts you should know about FreeDOS " title="4 cool facts you should know about FreeDOS "></p><p>在 90 年代早期，我是一位 DOS 的 “資深用户”。我用 DOS 做任何事，甚至寫我自己的工具來擴展 DOS 命令列。當然，我們有 Microsoft Windows，但是如果你還記得當時的計算機，Windows 3.1 並不是那麼好，我更喜歡在 DOS 中工作。</p><p>你可能會理解，在 1994 年，當微軟（在科技雜誌的採訪中）宣佈下一個版本的 Windows 將會取消 MS-DOS 時，我感到有些困惑和不安。我想：“如果 Windows 3.2 或 4.0 看起來像 Windows 3.1 一樣，我不想用它了。” 我四處選擇，並決定如果 DOS 要繼續下去的話，那麼需要有人創建一個 DOS，在 MS-DOS 消失的時候，讓每個人都可以使用它。</p><p>因此在 1994 年 6 月 29 日，我在 Usenet 討論組寫了一個信息，宣佈了新的 “free DOS” 項目：</p><blockquote><p>幾個月前，我發表了一篇關於啓動公共領域版本的 DOS 的文章。當時對此的普遍支持是很強烈的，並且很多人同意這個聲明，“開始編寫！”</p><p>所以，我要……</p><p>宣佈首次嘗試製作 PD-DOS。我寫了一份描述這樣一個項目的目標和工作綱要的“清單”，以及一份“任務清單”，展示了需要編寫些什麼。我會在這裏發貼，讓我們進行討論。</p></blockquote>',7)),a("p",null,[e[1]||(e[1]=o("今天，已經是 23 年之後了，",-1)),r(t,{href:"https://opensource.com/article/17/6/www.freedos.org"},{default:s(()=>[...e[0]||(e[0]=[o("FreeDOS",-1)])]),_:1}),e[2]||(e[2]=o(" 仍在變得更強大！",-1))]),e[17]||(e[17]=l('<p>我們繼續發佈有新功能和特性的版本。我們的 FreeDOS 1.2 發佈於 2016 年 12 月 25 日，這證明很多人喜歡使用和在 FreeDOS 上工作。當我回顧我們的歷史，有一個你應該知道的關於 FreeDOS 的很酷的事實列表：</p><h3 id="可以立即開始的軟件開發" tabindex="-1">可以立即開始的軟件開發 <a class="header-anchor" href="#可以立即開始的軟件開發" aria-label="Permalink to “可以立即開始的軟件開發”">​</a></h3><p>在原始的 DOS 中，很難做任何編程。DOS 提供了一個簡單的 BASIC 解釋器，一些用户可以用 DEBUG 做些精巧的事情，但是你不能在 DOS 中做真正編程的事情。在 FreeDOS 中，有許多不同的工具做軟件開發：編譯器、彙編器、調試器、解釋器和編寫腳本。在你安裝 FreeDOS 之後，你可以立即用 C、彙編、Pascal、Perl 和幾種其他語言編寫代碼。</p><h3 id="瀏覽-web" tabindex="-1">瀏覽 web <a class="header-anchor" href="#瀏覽-web" aria-label="Permalink to “瀏覽 web”">​</a></h3><p>DOS 是一個老式系統，並且原本不支持開箱即用的網絡。通常，你必須安裝硬件的設備驅動程序才能連接到網絡，一般是像 IPX 這樣的簡單網絡。只有很少的系統會支持 TCP/IP。</p><p>在 FreeDOS 中，我們不僅包含了 TCP/IP 網絡棧，我們還包含了讓你瀏覽 web 的工具和程序。使用 Dillo 作為圖形 web 瀏覽體驗，或則使用 Lynx 以純文本形式瀏覽 web。如果你只想要抓取 HTML 代碼並自己操作，使用 Wget 或者 Curl。</p><h3 id="玩很棒的-dos-遊戲" tabindex="-1">玩很棒的 DOS 遊戲 <a class="header-anchor" href="#玩很棒的-dos-遊戲" aria-label="Permalink to “玩很棒的 DOS 遊戲”">​</a></h3><p>我們知道很多的人安裝 FreeDOS 來玩經典的 DOS 遊戲，運行古老的商業程序或者做嵌入式開發。使用 FreeDOS 的許多人只是拿來玩遊戲，那對我們來説是件很酷的事，因為一個遊戲很老並不意味着它很無趣。DOS 有許多很棒的遊戲！安裝你最喜歡的經典遊戲，你會玩得很開心。</p><p>因為有如此多的人使用 FreeDOS 來玩遊戲，我們現在包含了不同的 DOS 遊戲。FreeDOS 1.2 包含了第一人稱射擊遊戲像 FreeDOOM、街機射擊像 Kiloblaster、飛行模擬器像 Vertigo 等等。我們目標是為每人提供一些東西。</p><h3 id="freedos-現在已經比-ms-dos-活的更久了" tabindex="-1">FreeDOS 現在已經比 MS-DOS 活的更久了 <a class="header-anchor" href="#freedos-現在已經比-ms-dos-活的更久了" aria-label="Permalink to “FreeDOS 現在已經比 MS-DOS 活的更久了”">​</a></h3><p>微軟在 1981 年 8 月發佈了 MS-DOS 1.0。13 年之後，微軟在 1995 年 8 月發佈 Windows 95 後拋棄了 MS-DOS，雖然 MS-DOS 直到 2000 年 9 月之前一直存在。總的來説，MS-DOS 是一件已經存在了 19 年的東西。</p><p>我們在 1994 年 6 月宣佈了 FreeDOS，並且在同年的 9 月發佈了第一個 Alpha 版本。因此 FreeDOS 已經大約有 23 年了，比微軟的 MS-DOS 還多了幾年。確實我們在 FreeDOS 上努力的時間已經比 MS-DOS 更長了。而 FreeDOS 還將繼續保持強大。</p><p>FreeDOS 與其他 DOS 另外一個重要的不同是_它仍在開發中_。我們有一個積極的開發者社區，並一直在尋找新人來幫助。請加入社區並幫助構造新的 FreeDOS 版本吧。</p><p>（題圖： FreeDOS）</p><hr><p>作者簡介：</p><p>Jim Hall - 我是 FreeDOS 項目的創始人和協調者。我還擔任 GNOME 基金董事會董事。在工作中，我是明尼蘇達州拉姆齊縣的首席信息官。在業餘時間，我致力於開源軟件的可用性，並通過 Outreachy（之前針對婦女的 GNOME Outreach 項目）指導 GNOME 中的可用性測試。</p><hr>',18)),a("p",null,[e[4]||(e[4]=o("via: ",-1)),r(t,{href:"https://opensource.com/article/17/6/freedos-still-cool-today"},{default:s(()=>[...e[3]||(e[3]=[o("https://opensource.com/article/17/6/freedos-still-cool-today",-1)])]),_:1})]),a("p",null,[e[8]||(e[8]=o("作者：",-1)),r(t,{href:"https://opensource.com/users/jim-hall"},{default:s(()=>[...e[5]||(e[5]=[o("Jim Hall",-1)])]),_:1}),e[9]||(e[9]=o(" 譯者：",-1)),r(t,{href:"https://github.com/geekpi"},{default:s(()=>[...e[6]||(e[6]=[o("geekpi",-1)])]),_:1}),e[10]||(e[10]=o(" 校對：",-1)),r(t,{href:"https://github.com/wxy"},{default:s(()=>[...e[7]||(e[7]=[o("wxy",-1)])]),_:1})]),a("p",null,[e[13]||(e[13]=o("本文由 ",-1)),r(t,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...e[11]||(e[11]=[o("LCTT",-1)])]),_:1}),e[14]||(e[14]=o(" 原創編譯，",-1)),r(t,{href:"https://linux.cn/"},{default:s(()=>[...e[12]||(e[12]=[o("Linux中國",-1)])]),_:1}),e[15]||(e[15]=o(" 榮譽推出",-1))])])}const h=S(i,[["render",n]]);export{w as __pageData,h as default};
